const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='slowbrew-v1';let records=[];try{records=JSON.parse(localStorage.getItem(KEY)||'[]');if(!Array.isArray(records))records=[]}catch{records=[]}let extras=records.filter(r=>r._beanProfile||r._preferences);let customRecipes=records.filter(r=>r._customRecipe);records=records.filter(r=>!r._customRecipe&&!r._beanProfile&&!r._preferences);const allRecipes=()=>[...customRecipes,...recipes];let page='home',filter='全部',query='',editing=null;
const recipes=[{id:'daily',title:'日常 V60',author:'你的日常起點',method:'V60',dose:12,water:200,temp:90,clicks:24,seconds:180,steps:'0:00 注水 40g，悶蒸 30 秒\n0:30 加至 120g\n1:15 加至 200g，等待流完',desc:'簡單三段注水。先用熟悉嘅豆，慢慢搵出你嘅甜蜜點。',source:''},{id:'switch',title:'Switch 全浸泡',author:'入門參考食譜',method:'Hario Switch',dose:12,water:200,temp:86,clicks:24,seconds:180,steps:'0:00 關閥，加水至 200g\n輕輕攪拌，確保咖啡粉充分濕潤\n2:00 開閥，記錄實際流完時間',desc:'先浸泡，再開閥。你熟悉嘅 12g / 200g，方便逐杯調整。',source:''},{id:'46',title:'粕谷哲 · 4:6',author:'Tetsu Kasuya · 均衡參考版',method:'V60',dose:20,water:300,temp:92,clicks:28,seconds:210,steps:'0:00 注水 60g\n0:45 加至 120g\n1:30 加至 180g\n2:15 加至 240g\n3:00 加至 300g，等待流完',desc:'五次注水，每次 60g。前 40% 與後 60% 分段調整；時間及 C40 格數為參考起點。',source:'https://kurasu.kyoto/blogs/kurasu-journal/2016-world-brewers-cup-champion-tetsu-kasuya'}];
const demo=[{id:'demo1',bean:'El Limoncillo · Javanica',method:'Hario Switch',dose:12,water:200,temp:86,clicks:24,seconds:180,rating:3,sweet:2,acid:2,bitter:1,body:2,notes:'果香柔和，口感稍薄。下次想試磨細兩格。',date:'2026-10-25T09:30',demo:true},{id:'demo2',bean:'Mi Finquita · Catuai',method:'V60',dose:15,water:225,temp:90,clicks:26,seconds:195,rating:4,sweet:4,acid:2,bitter:2,body:3,notes:'堅果、焦糖感，甜感幾舒服。',date:'2026-10-24T10:15',demo:true},{id:'demo3',bean:'我的日常咖啡豆',method:'V60',dose:20,water:300,temp:92,clicks:28,seconds:210,rating:4,sweet:3,acid:3,bitter:2,body:3,notes:'用 4:6 法試沖，口感乾淨，想再甜少少。',date:'2026-10-23T14:00',demo:true}];
const art=`<svg viewBox="0 0 300 230" fill="none" aria-label="手沖咖啡插畫" role="img"><ellipse cx="154" cy="205" rx="116" ry="13" fill="#d5cfbd"/><path d="M92 147h112l-13 48H107z" fill="#efeee5" stroke="#868b75" stroke-width="2"/><path d="M204 154c40-4 30 38-8 29" stroke="#868b75" stroke-width="5"/><ellipse cx="148" cy="148" rx="55" ry="9" fill="#82664e"/><path d="M76 55h146l-48 83h-49z" fill="#b4bfa6" stroke="#77876c" stroke-width="2"/><path d="M92 61l44 68m-15-68 23 68m9-68v68m28-68-22 68m42-68-34 68" stroke="#8a9c7f" stroke-width="2"/><ellipse cx="149" cy="55" rx="73" ry="13" fill="#e2e4d6" stroke="#77876c" stroke-width="2"/><ellipse cx="149" cy="55" rx="56" ry="8" fill="#8c715a"/><path d="M143 16c-18 12 14 15-1 28m22-36c-15 12 14 17-1 29" stroke="#a3a68e" stroke-width="2" stroke-linecap="round"/><path d="M233 121c12-15 21-12 25-21m-13 12 5 13" stroke="#919a80" stroke-width="2"/><circle cx="55" cy="157" r="6" fill="#b99f75"/><circle cx="246" cy="177" r="4" fill="#b99f75"/></svg>`;
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',2700)}
function persist(next){if(window.coffeeCloud)return window.coffeeCloud.persist(next);try{localStorage.setItem(KEY,JSON.stringify(next));records=next;return true}catch{toast('儲存失敗，請檢查瀏覽器儲存空間');return false}}
function card(r){return `<article class="card"><div class="card-top"><span>${esc(r.date.replace('T',' · '))}</span><span class="badge">${esc(r.method)}</span></div><h3 ${r.demo?'':'translate="no"'}>${esc(r.bean)}</h3><span class="example">${r.demo?'示範紀錄 · 非你的實際評分':'你的沖煮紀錄'}</span><div class="params"><div><small>粉 / 水</small><b>${r.dose}g / ${r.water}g</b></div><div><small>水溫</small><b>${r.temp}°C</b></div><div><small>C40 研磨</small><b>${r.clicks} clicks</b></div></div><p class="note" ${r.demo||!r.notes?'':'translate="no"'}>${esc(r.notes||'未有味道筆記')}</p><div class="card-bottom"><span class="stars">${r.rating?'★'.repeat(+r.rating)+'☆'.repeat(5-r.rating):'未評分'}</span><button class="text-link" data-detail="${esc(r.id)}">查看呢一杯 ↗</button></div></article>`}
function render(){document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===page));const rows=records.length?records:demo;const shown=rows.filter(r=>(filter==='全部'||r.method===filter)&&r.bean.toLowerCase().includes(query.toLowerCase()));const rated=records.filter(r=>+r.rating);$('#content').innerHTML=page==='home'?`<div class="page-title"><div><h1>沖煮日誌</h1><p class="subtitle">好味道，從記低每一杯開始。</p></div><button class="primary" data-new>＋ 記錄一杯</button></div><div class="stats"><div class="stat"><small>已記錄沖煮</small><strong>${records.length}<span>杯</span></strong></div><div class="stat"><small>平均滿意度</small><strong>${rated.length?(rated.reduce((n,r)=>n+ +r.rating,0)/rated.length).toFixed(1):'—'}<span>/ 5</span></strong></div><div class="stat"><small>試過嘅咖啡豆</small><strong>${new Set(records.map(r=>r.bean)).size}<span>款</span></strong></div></div><div class="section-head"><h3>${records.length?'最近嘅每一杯':'先睇吓記錄效果'} <span class="example">${records.length?'':'以下為示範'}</span></h3><div class="filters">${['全部','Hario Switch','V60'].map(f=>`<button class="chip ${filter===f?'active':''}" data-filter="${f}">${f}</button>`).join('')}</div></div><div class="toolbar"><input id="search" placeholder="搜尋咖啡豆…" value="${esc(query)}" aria-label="搜尋咖啡豆"><button class="text-link" id="export">↓ 匯出我的紀錄</button></div><div class="grid" id="cards">${shown.map(card).join('')||'<div class="empty">暫時未有符合嘅紀錄。</div>'}</div>`:page==='recipes'?`<div class="page-title"><div><h1>食譜收藏</h1><p class="subtitle">用一個起點，沖出自己嘅版本。</p></div><button class="primary" data-add-recipe>＋ 新增食譜</button></div><div class="recipe-note">每份食譜都可以修改粉量、水溫、時間、C40 格數及流程。名家食譜標明參考來源；C40 格數為本網站參考值，並非咖啡師原定規格。</div><div class="grid recipe-grid">${allRecipes().map(r=>`<article class="card"><div class="card-top"><span class="badge">${esc(r.method)}</span><span>0${allRecipes().indexOf(r)+1}</span></div><h3 ${r._customRecipe?'translate="no"':''}>${esc(r.title)}</h3><p>${esc(r.author)}</p><p ${r._customRecipe?'translate="no"':''}>${esc(r.desc)}</p><div class="params"><div><small>粉 / 水</small><b>${r.dose}g / ${r.water}g</b></div><div><small>水溫</small><b>${r.temp}°C</b></div><div><small>參考時間</small><b>${Math.floor(r.seconds/60)}:${String(r.seconds%60).padStart(2,'0')}</b></div></div><p class="detail" ${r._customRecipe?'translate="no"':''}>${esc(r.steps)}</p>${r.source?`<a class="recipe-source" href="${r.source}" target="_blank" rel="noopener">參考來源 ↗</a>`:''}<div><button class="primary" data-recipe="${r.id}">用呢份食譜沖一杯 →</button></div></article>`).join('')}</div>`:`<div class="page-title"><div><h1>我的咖啡豆</h1><p class="subtitle">每包豆，都有自己嘅甜蜜點。</p></div><button class="primary" data-new>＋ 記錄一杯</button></div><div class="grid">${[...new Set(records.map(r=>r.bean))].map(bean=>{const rr=records.filter(r=>r.bean===bean);const best=rr.filter(r=>+r.rating).sort((a,b)=>b.rating-a.rating)[0];return `<article class="card"><span class="badge">${rr.length} 杯紀錄</span><h3 translate="no" style="margin-top:20px">${esc(bean)}</h3><p>${best?`最高滿意度 ${best.rating}/5 · ${best.clicks} clicks · ${best.temp}°C`:'尚未有評分'}</p><button class="text-link" data-bean="${esc(bean)}">查看呢包豆嘅紀錄 →</button></article>`}).join('')||'<div class="empty">記錄第一杯後，咖啡豆會自動整理喺呢度。<br>第一版先以豆名分組。</div>'}</div>`;}
const form=$('#brewform');const ratingNames={rating:'整體滿意度',sweet:'甜感',acid:'酸感',bitter:'苦感',body:'厚實度'};$('#ratings').innerHTML=Object.entries(ratingNames).map(([k,v])=>`<label class="rating">${v}<select name="${k}"><option value="">未評分</option>${[1,2,3,4,5].map(n=>`<option value="${n}">${n} / 5${k==='rating'?(n===1?' · 不喜歡':n===5?' · 好鍾意':''):(n===1?' · 低':n===5?' · 高':'')}</option>`).join('')}</select></label>`).join('');
function ratio(){const d=+form.elements.dose.value,w=+form.elements.water.value;$('#ratio').value=d?'1 : '+(w/d).toFixed(1):'—'}
function localTime(){const d=new Date();return new Date(d-d.getTimezoneOffset()*60000).toISOString().slice(0,16)}
function openBrew(r){form.reset();editing=null;form.elements.date.value=localTime();if(r){for(const [k,v]of Object.entries(r))if(form.elements[k])form.elements[k].value=v;form.elements.date.value=localTime()}ratio();$('#editor').showModal()}
$('#preset').onchange=e=>{const r=allRecipes().find(r=>r.id===e.target.value);if(r){for(const [k,v]of Object.entries(r))if(form.elements[k])form.elements[k].value=v;ratio()}};
form.oninput=ratio;$('#close').onclick=()=>$('#editor').close();
form.onsubmit=e=>{e.preventDefault();if(!form.reportValidity())return;const r=Object.fromEntries(new FormData(form));for(const k of ['dose','water','temp','clicks','seconds','rating','sweet','acid','bitter','body'])r[k]=r[k]===''?null:+r[k];r.bean=r.bean.trim();if(!r.bean){toast('請填寫咖啡豆名');return}if(window.saveCustomRecipe?.(r))return;r.id=editing||('brew-'+Date.now()+'-'+Math.random().toString(36).slice(2,6));const next=editing?records.map(x=>x.id===editing?r:x):[r,...records];if(persist(next)){$('#editor').close();page='home';query='';filter='全部';render();toast(window.coffeeCloud?window.coffeeCloud.savedMessage():'已儲存呢一杯 ☕')}};
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.page){page=b.dataset.page;render()}if(b.hasAttribute('data-new'))openBrew();if(b.dataset.filter){filter=b.dataset.filter;render()}if(b.dataset.recipe)openBrew(allRecipes().find(r=>r.id===b.dataset.recipe));if(b.dataset.bean){page='home';query=b.dataset.bean;filter='全部';render()}if(b.dataset.detail){const r=[...records,...demo].find(r=>r.id===b.dataset.detail);openBrew(r);if(!r.demo){editing=r.id;form.elements.date.value=r.date}toast(r.demo?'示範已帶入；儲存後會成為你嘅新紀錄':'可以修改參數、日期及評分')}if(b.id==='export'){const blob=new Blob([JSON.stringify({version:3,records,recipes:customRecipes,extras},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='coffee-journal.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('已匯出 '+records.length+' 杯紀錄')}});
document.addEventListener('input',e=>{if(e.target.id==='search'){query=e.target.value;const rows=records.length?records:demo;$('#cards').innerHTML=rows.filter(r=>(filter==='全部'||r.method===filter)&&r.bean.toLowerCase().includes(query.toLowerCase())).map(card).join('')||'<div class="empty">暫時未有符合嘅紀錄。</div>'}});
$('#date').textContent=new Intl.DateTimeFormat('zh-HK',{year:'numeric',month:'long',day:'numeric',weekday:'long'}).format(new Date());render();
const stageScript=document.createElement('script');stageScript.src='stages.js';stageScript.onload=()=>{const templates=document.createElement('script');templates.src='kasuya-recipes.js';templates.onload=()=>{const rules=document.createElement('script');rules.src='brew-advice.js';rules.onload=()=>{const ui=document.createElement('script');ui.src='suggestions.js';ui.onload=()=>{const scaling=document.createElement('script');scaling.src='recipe-scale.js';scaling.onload=()=>{const custom=document.createElement('script');custom.src='custom-recipes.js';custom.onload=()=>{window.initRecipeWaterMix?.();const core=document.createElement('script');core.src='experience-core.js';core.onload=()=>{const experience=document.createElement('script');experience.src='experience.js';experience.onload=()=>window.startCoffeeCloud?.({getRecords:()=>[...records,...customRecipes,...extras],replaceRecords:next=>{records=next.filter(r=>!r._customRecipe&&!r._beanProfile&&!r._preferences);customRecipes=next.filter(r=>r._customRecipe);extras=next.filter(r=>r._beanProfile||r._preferences);window.refreshCustomRecipes?.();window.refreshCoffeeExperience?.();render()},closeAccountViews:()=>{document.querySelectorAll('dialog[open]').forEach(d=>d.close());editing=null;query='';filter='全部'}});document.body.append(experience)};document.body.append(core)};document.body.append(custom)};document.body.append(scaling)};document.body.append(ui)};document.body.append(rules)};document.body.append(templates)};document.body.append(stageScript);
const mixScript=document.createElement('script');mixScript.src='water-mix.js';document.body.append(mixScript);
